window.MONSTER_CHUNK_28 = [{"name":"Lacridaemon","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"}],"auras":["weeping aura 100 ft."],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":4,"will":5,"dr":"5/good or silver","immunities":["acid","death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":14,"speed":[{"type":"land","speed":40}],"melee":"bite +6 (1d4+2 plus 1d4 acid and poison), 2 claws +7 (1d4+2 plus 1d4 acid)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poisonous tears"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"pass without trace"}]},{"frequency":"1/day","spells":[{"spell":"hold person"},{"spell":"invisibility"},{"spell":"snare"},{"spell":"summon","details":"level 4, 1 lacridaemon, 50%"}]},{"frequency":"3/day","spells":[{"spell":"overwhelming grief"},{"spell":"teleport","details":"self plus 50 lbs. of objects only"}]}],"strength":14,"dexterity":17,"constitution":14,"intelligence":11,"wisdom":13,"charisma":12,"baseatk":4,"cmb":6,"cmd":19,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+14 jump"},{"skill":"Bluff","value":8},{"skill":"Climb","value":9},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":10}],"languages":["Abyssal","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Abaddon)"],"organizations":["solitary","pair","lurk (3-6)"],"treasure":"standard","description_visual":"Sobbing uncontrollably, this gray-skinned creature possesses thin legs ending in black cloven hooves, as well as a ferocious, manic grin. Its flesh is torn and scratched even down to the tip of its misshapen tail, while a patchwork sheet of dirty ice covers its body. Its tears sizzle violently as they hit the ground.","source":"Horsemen Of The Apocalypse","special_abilities":[{"type":"Poisonous Tears","kind":"Su","details":"A lacridaemon's tears are poisonous to other creatures. As a move action that provokes an attack of opportunity, a lacridaemon can coat both of its claws with its tears, giving its next attack the possibility of poisoning its victim. A lacridaemon must attack with its claws on the same round or the round immediately after it applies its tears in order to use this ability; after that time, the tears lose their potency. Once it has attacked a creature using its tear-coated claws, a lacridaemon must reapply the tears again in order to use this ability. A lacridaemon's bite attack is always treated as having its poisonous tears applied to it. Lacridaemon poison: Injury; save Fortitude DC 14; frequency 1/round for 6 rounds; effect 1 Wis plus staggered for 1 round; cure 2 consecutive saves."},{"type":"Weeping Aura","kind":"Su","details":"A lacridaemon emits an invisible aura that sounds like the whimpers of a crying child. The whimpers sound almost as if they're coming from all directions at once, or perhaps from one's own mind, disorienting those within the aura's area. Any creature that enters this area takes a -5 penalty on Survival checks to avoid becoming lost. Creatures within the aura's range need not be able to physically hear the whimpers in order to be affected by this ability (and those who try to identify its origin so they can get nearer take a -5 penalty on their Perception checks to do so). A lacridaemon can suppress or reactivate its aura as a free action, and the effects from multiple lacridaemon auras stack (up to a maximum penalty of -20). This aura is a sonic, mind-affecting effect."}],"description":"Among the least powerful of Abaddon's daemons, though still exceedingly dangerous, lacridaemons personify death by neglect or exposure to the elements, such as that suffered by those who become lost in the wilderness and die far from help, or are trapped in an enclosed space (like a collapsed mine) and left to slowly expire. Sadly, children are more likely to become lacridaemons than any other type of daemon, and while it's rare for children to be truly evil, those unfortunate children who die from neglect and abuse, or who are abandoned by their parents, are at risk of being twisted and made savage by the experience. Lacridaemons' misery is in stark contrast to their savage nature, and given the opportunity, they viciously lash out, furiously attacking their mortal victims. Burning tears of acid and horrific powers used to strand mortals in perilous conditions make lacridaemons effective combatants against unwary enemies, and their abilities are compounded when the daemons are encountered as a wailing, weeping group.\n\nEcology\n\nPitiful creatures, most lacridaemons suffer in death as their mortal incarnations did in life, consumed by feelings of abandonment, self-pity, and a gnawing sense of loneliness. They often spawn from the souls of evil mortals who died alone and abandoned-exiled criminals, reclusive and corrupt nobles, or those who died from intense exposure to the natural elements, such as by freezing to death or dying of thirst. They are thus often servants of the Horseman of Famine, who makes use of their skills in luring mortals well beyond the edges of civilization, where they ultimately perish due to lack of nourishment.\n\nWracked by an enduring and incurable loneliness even in death, these fiends yearn for the companionship they died without, but only so they can attack and prey upon the souls of those who denied them help in life. They still call out for aid, whispering with a subtle telepathy as well as calling out with weak, pleading voices, begging for help and comfort. In Abaddon, their calls mostly draw out the hunted-namely those evil souls of Abaddon who would seek to take advantage of a stranded innocent-while on the Material Plane they bring forth all manner of doomed altruists. They turn on those who arrive, attacking anyone who would show them the benevolence denied or unattainable to them in life. Of course, the very notion that their daemonic nature might be inf luenced by the dim memories of a mortal soul is disgusting to them, and most reject the idea as blasphemous.\n\nHabitat & Society\n\nBef itting their nature, most lacridaemons wander the fringes of daemonic society, abhorring the cities and citadels that populate the greater realms of the Four and their subordinate lords. This self-selected exile has several consequences. First, it ensures that they, as a caste of daemons, receive only the scraps of mortal souls, and rarely does any lacridaemon rise to a position of prominence within Abaddon. Their wandering also brings them into considerable conf lict with the various non-daemonic natives of Abaddon, including nightmares and night hags-but when confronted by powerful foes or outnumbered, lacridaemons usually simply flee. Lacridaemons take great pleasure in pursuing the hunted, leading the already stranded souls further astray throughout the vast wastelands of Abaddon. These hunted never die of starvation or malnourishment, instead subsisting in a constant state of agonizing hunger, and the lacridaemon takes great pleasure in causing such suffering. Solitary and xenophobic, lacridaemons shun the company of other creatures except for other lacridaemons, and even then the fiends largely just cluster together, interacting at a bare minimum. These small lurks of lacridaemons are especially dangerous when encountered in the wild; their maddening whines for help often cause entire parties of travelers to become disoriented and lose their way in treacherous lands.\n\nWhile on the Material Plane, lacridaemons gravitate toward hostile environs such as vast swaths of tundra, brutally hot deserts, and inhospitable swamplands. Occasionally, a lacridaemon will appear near the border of an oasis city or remote outpost, waiting for travelers to leave on the next leg of their journey. The lacridaemon will then follow the unwitting travelers at a distance, waiting until they are far from civilization before coming close enough to let its mind-affecting sobs be known. Lacridaemons use their pitiful whimpering to string prey along for days at a time, until the unfortunate victim has run out of food or water and is on the brink of death. When this occurs, the cunning daemon finally confronts its prey, revealing the true source of the weeping. If it needs to attack, a lacridaemon does so swiftly, savoring the body and reveling in the death of yet another abandoned soul, shedding its perpetual tears all the while.","ecology":"Pitiful creatures, most lacridaemons suffer in death as their mortal incarnations did in life, consumed by feelings of abandonment, self-pity, and a gnawing sense of loneliness. They often spawn from the souls of evil mortals who died alone and abandoned-exiled criminals, reclusive and corrupt nobles, or those who died from intense exposure to the natural elements, such as by freezing to death or dying of thirst. They are thus often servants of the Horseman of Famine, who makes use of their skills in luring mortals well beyond the edges of civilization, where they ultimately perish due to lack of nourishment.\n\nWracked by an enduring and incurable loneliness even in death, these fiends yearn for the companionship they died without, but only so they can attack and prey upon the souls of those who denied them help in life. They still call out for aid, whispering with a subtle telepathy as well as calling out with weak, pleading voices, begging for help and comfort. In Abaddon, their calls mostly draw out the hunted-namely those evil souls of Abaddon who would seek to take advantage of a stranded innocent-while on the Material Plane they bring forth all manner of doomed altruists. They turn on those who arrive, attacking anyone who would show them the benevolence denied or unattainable to them in life. Of course, the very notion that their daemonic nature might be inf luenced by the dim memories of a mortal soul is disgusting to them, and most reject the idea as blasphemous.","habitat_society":"Bef itting their nature, most lacridaemons wander the fringes of daemonic society, abhorring the cities and citadels that populate the greater realms of the Four and their subordinate lords. This self-selected exile has several consequences. First, it ensures that they, as a caste of daemons, receive only the scraps of mortal souls, and rarely does any lacridaemon rise to a position of prominence within Abaddon. Their wandering also brings them into considerable conf lict with the various non-daemonic natives of Abaddon, including nightmares and night hags-but when confronted by powerful foes or outnumbered, lacridaemons usually simply flee. Lacridaemons take great pleasure in pursuing the hunted, leading the already stranded souls further astray throughout the vast wastelands of Abaddon. These hunted never die of starvation or malnourishment, instead subsisting in a constant state of agonizing hunger, and the lacridaemon takes great pleasure in causing such suffering. Solitary and xenophobic, lacridaemons shun the company of other creatures except for other lacridaemons, and even then the fiends largely just cluster together, interacting at a bare minimum. These small lurks of lacridaemons are especially dangerous when encountered in the wild; their maddening whines for help often cause entire parties of travelers to become disoriented and lose their way in treacherous lands.\n\nWhile on the Material Plane, lacridaemons gravitate toward hostile environs such as vast swaths of tundra, brutally hot deserts, and inhospitable swamplands. Occasionally, a lacridaemon will appear near the border of an oasis city or remote outpost, waiting for travelers to leave on the next leg of their journey. The lacridaemon will then follow the unwitting travelers at a distance, waiting until they are far from civilization before coming close enough to let its mind-affecting sobs be known. Lacridaemons use their pitiful whimpering to string prey along for days at a time, until the unfortunate victim has run out of food or water and is on the brink of death. When this occurs, the cunning daemon finally confronts its prey, revealing the true source of the weeping. If it needs to attack, a lacridaemon does so swiftly, savoring the body and reveling in the death of yet another abandoned soul, shedding its perpetual tears all the while."},{"name":"Lamhigyn","cr":3,"xp":800,"alignment":"CE","size":"Small","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":27,"hd":"5d10","hdvalue":5,"fort":4,"ref":6,"will":2,"speed":[{"type":"land","speed":10},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"sting +7 (1d3+1 plus poison), 2 wings +2 (1d3 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"},{"type":"wrap wings"}],"strength":12,"dexterity":15,"constitution":11,"intelligence":5,"wisdom":12,"charisma":8,"baseatk":5,"cmb":5,"cmb_special":"+4 vs. grapple","cmd":17,"cmd_special":"+4 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Fly","value":16},{"skill":"Perception","value":9},{"skill":"Stealth","value":14}],"languages":["Abyssal"],"environments":["any (Abyss)"],"organizations":["solitary","pair","clutch (3-9)","hive (10-30)"],"treasure":"none","description_visual":"This small, three-eyed creature lets out garbled, piercing shrieks as it flits about on ragged batlike wings, its barbed tail flicking with menace.","source":"AP 76","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 12; frequency 1/round for 4 rounds; effect 1d4 Wis damage; cure 2 consecutive saves."},{"type":"Wrap Wings","kind":"Ex","details":"When a lamhigyn uses its wing attacks to grab an opponent, it wraps its wings around its opponent's head, causing the victim to gain the blinded condition for as long as the lamhigyn grapples that creature. A grappling lamhigyn automatically deals wing damage while grappling, but it takes the normal -2 penalty on attack rolls for its sting attack. This ability has no effect on creatures that don't have sensory organs in their heads."}],"description":"Simple creatures, lamhigyns emerged from the chaotic fabric of the Abyss. Abyssal pests might be a good description of these strange creatures; their stings have left many adventurers insane and debilitated, opportune victims for the Abyss's insatiable predators. Viewing intruders with evil disdain, lamhigyns are always looking for new victims, which they slowly lap apart, piece by piece, with their rasping mouths.\n\nLamhigyns are strange-looking creatures that are often characterized by mortals visiting the Abyss as overgrown, flying tadpoles with the wings of a bat and a stinger-tipped tail. They lurk within dark places in the Abyss and in similarly lightless places on the Material Plane near rifts to their homeland. Their bulbous, unblinking eyes are vaguely froglike, and are often the first and last things unprepared adventurers see, as the pesky creatures are fond of wrapping their wings around their victims' heads to blind their prey. Their tiny mouths house thick tongues that flicker when intruders arrive.\n\nLamhigyns have thick, scaly skin on their bodies ranging in color from red to green. Though lamhigyns are typically encountered flying, on the ground they stand on four insectile legs that they keep tucked beneath them while nesting. Although they are small, their 2-foot-high, 8-pound bodies pack an impressive punch when hurtling through the air at their victims.\n\nEcology\n\nLamhigyns are pests from another plane and have no proper place in the Material Plane's natural order. Chaotic creatures with an inherent streak of evil, they lie in wait, eager for mortal life to happen by. When this occurs, lamhigyns instantly attack and try to immobilize their victims before slowly devouring them alive.\n\nLamhigyns that have slipped through to the Material Plane breed in dark caves and shadowed forests. Their mating rituals are dangerous, messy affairs. Approximately once every year, the fertile females- which are nearly indistinguishable from the males- fly to the highest corners of the cave or den where they live. There, they squawk uncontrollably. The males hurtle toward these females; the ensuing flapping and screeching results in the females' three or five eggs becoming fertilized. The females then lay these eggs in slime-covered clusters, where they incubate for 6 to 8 weeks before hatching. Lamhigyn mothers typically die shortly after laying their eggs, their bodies exhausted by the violent process of reproduction.\n\nAs they grow, lamhigyn hatchlings join any others of their kind in nearby caverns or find their own comfortable, dark places in which to live. Some find the Material Plane uncomfortable and spend all of their energy trying to find a way back to the home world they've never known but feel intrinsically drawn to.\n\nBeing from the Abyss, lamhigyns don't need to sleep; however, many choose to stay very still within the darkness-their wings wrapped around their bodies and their tiny legs curled underneath-waiting for the simple pleasure of scaring anything that may wander nearby. Similarly, lamhigyns have no need or desire to eat, but they spend much of their energy focused on predation. Though they don't require sustenance, they delight in bloodshed and violence.\n\nHabitat & Society\n\nFound in all corners of the Abyss, lamhigyns often slip through to the Material Plane (or other planes in the Great Beyond) as a result of being caught up by portals or flying too close to a rift between worlds. The greatest known rift on Golarion is the Worldwound. Here, lamhigyns are found in great abundance, almost invariably in caves, cliffs, or even the fabric of the Worldwound itself-sites chosen because of their similarity to lamhigyns' darkened homes in the Abyss. In fact, some of these simple-minded creatures believe this region of Golarion is part of the Abyss. For the most part, however, they're more delighted with the abundance of food in the Worldwound than they are concerned with geography.\n\nWhen it comes to their own kind, lamhigyns can be volatile and violent in nature. In general, they tend to get along with other lamhigyns, though almost anything can set them off: living in too close proximity to each other, mating disputes, or arguments over the torn bodies of victims. When this happens, lamhigyns turn the full force of their chaotic fury onto each other, tearing and grappling until only one-sometimes none-of the bizarre creatures remain. When lamhigyns turn against each other, they are even more vicious than when they attack other creatures. Sometimes a petty squabble between two boisterous lamhigyns can spread through an entire hive as they infect each other with a chaotic bloodlust. Before long, entire caverns full of lamhigyns erupt in screeching echoes that crash against the rocky walls.\n\nWhen they're not fighting among themselves, lamhigyns occupy shared spaces in noisy, flapping hives, waiting for hapless creatures to stumble into their dens. Intelligent creatures susceptible to fear-such as adventurers, creatures whose minds have been warped by the Worldwound's infestations, or unlucky natives- then suffer lamhigyns' gleeful ire. Lamhigyns ignore most normal animals unless they have waited too long for fresh prey and have grown bored. When it comes to victims, lamhigyns prefer those that can think and walk, for they provide the most deliciously terrified reactions. There isn'thing lamhigyns love more than to tear the life from terrified, screaming humans while they are out of their minds with fear.\n\nLamhigyns fill parts of the Abyss like pigeons fill large cities, and many demons regard the creatures as terrible pests. Some demons take to hunting the creatures for target practice or pest control. Lamhigyns avoid most demons, especially those more powerful than dretches.\n\nThey enjoy harassing dretches and quasits, however, and often flock around individuals, screeching and battering them with their wings. This hazing goes both ways, and in the Abyss dretch hunting parties scour caverns for lamhigyns.\n\nUnlike many other creatures, lamhigyns show little racial preference between a solitary existence or one with others of their kind. Although lamhigyns are more potent in groups, a single lamhigyn might occupy a small cave near the Worldwound for generations, waiting patiently for just one victim. Lamhigyns can live to be nearly 500 years old, though most die through acts of violence before reaching half that age.\n\nWhen the Worldwound first opened, lamhigyns poured through the tear in reality along with the demons. They were also some of the first to die, as the Sarkorians could defeat the strange, small creatures in combat more easily than they could the more durable demons. However, the winged creatures kept pouring through, foreshadowing the Abyssal onslaught that was to come. In short time, lamhigyns began populating the region, and now tens of thousands of these creatures are said to live near the Worldwound alone. Though lamhigyns are rare outside the Worldwound, their appearance elsewhere on Golarion is a sign that chaos-and the pain of draining, pesky stings-is sure to follow.","ecology":"Lamhigyns are pests from another plane and have no proper place in the Material Plane's natural order. Chaotic creatures with an inherent streak of evil, they lie in wait, eager for mortal life to happen by. When this occurs, lamhigyns instantly attack and try to immobilize their victims before slowly devouring them alive.\n\nLamhigyns that have slipped through to the Material Plane breed in dark caves and shadowed forests. Their mating rituals are dangerous, messy affairs. Approximately once every year, the fertile females- which are nearly indistinguishable from the males- fly to the highest corners of the cave or den where they live. There, they squawk uncontrollably. The males hurtle toward these females; the ensuing flapping and screeching results in the females' three or five eggs becoming fertilized. The females then lay these eggs in slime-covered clusters, where they incubate for 6 to 8 weeks before hatching. Lamhigyn mothers typically die shortly after laying their eggs, their bodies exhausted by the violent process of reproduction.\n\nAs they grow, lamhigyn hatchlings join any others of their kind in nearby caverns or find their own comfortable, dark places in which to live. Some find the Material Plane uncomfortable and spend all of their energy trying to find a way back to the home world they've never known but feel intrinsically drawn to.\n\nBeing from the Abyss, lamhigyns don't need to sleep; however, many choose to stay very still within the darkness-their wings wrapped around their bodies and their tiny legs curled underneath-waiting for the simple pleasure of scaring anything that may wander nearby. Similarly, lamhigyns have no need or desire to eat, but they spend much of their energy focused on predation. Though they don't require sustenance, they delight in bloodshed and violence.","habitat_society":"Found in all corners of the Abyss, lamhigyns often slip through to the Material Plane (or other planes in the Great Beyond) as a result of being caught up by portals or flying too close to a rift between worlds. The greatest known rift on Golarion is the Worldwound. Here, lamhigyns are found in great abundance, almost invariably in caves, cliffs, or even the fabric of the Worldwound itself-sites chosen because of their similarity to lamhigyns' darkened homes in the Abyss. In fact, some of these simple-minded creatures believe this region of Golarion is part of the Abyss. For the most part, however, they're more delighted with the abundance of food in the Worldwound than they are concerned with geography.\n\nWhen it comes to their own kind, lamhigyns can be volatile and violent in nature. In general, they tend to get along with other lamhigyns, though almost anything can set them off: living in too close proximity to each other, mating disputes, or arguments over the torn bodies of victims. When this happens, lamhigyns turn the full force of their chaotic fury onto each other, tearing and grappling until only one-sometimes none-of the bizarre creatures remain. When lamhigyns turn against each other, they are even more vicious than when they attack other creatures. Sometimes a petty squabble between two boisterous lamhigyns can spread through an entire hive as they infect each other with a chaotic bloodlust. Before long, entire caverns full of lamhigyns erupt in screeching echoes that crash against the rocky walls.\n\nWhen they're not fighting among themselves, lamhigyns occupy shared spaces in noisy, flapping hives, waiting for hapless creatures to stumble into their dens. Intelligent creatures susceptible to fear-such as adventurers, creatures whose minds have been warped by the Worldwound's infestations, or unlucky natives- then suffer lamhigyns' gleeful ire. Lamhigyns ignore most normal animals unless they have waited too long for fresh prey and have grown bored. When it comes to victims, lamhigyns prefer those that can think and walk, for they provide the most deliciously terrified reactions. There isn'thing lamhigyns love more than to tear the life from terrified, screaming humans while they are out of their minds with fear.\n\nLamhigyns fill parts of the Abyss like pigeons fill large cities, and many demons regard the creatures as terrible pests. Some demons take to hunting the creatures for target practice or pest control. Lamhigyns avoid most demons, especially those more powerful than dretches.\n\nThey enjoy harassing dretches and quasits, however, and often flock around individuals, screeching and battering them with their wings. This hazing goes both ways, and in the Abyss dretch hunting parties scour caverns for lamhigyns.\n\nUnlike many other creatures, lamhigyns show little racial preference between a solitary existence or one with others of their kind. Although lamhigyns are more potent in groups, a single lamhigyn might occupy a small cave near the Worldwound for generations, waiting patiently for just one victim. Lamhigyns can live to be nearly 500 years old, though most die through acts of violence before reaching half that age.\n\nWhen the Worldwound first opened, lamhigyns poured through the tear in reality along with the demons. They were also some of the first to die, as the Sarkorians could defeat the strange, small creatures in combat more easily than they could the more durable demons. However, the winged creatures kept pouring through, foreshadowing the Abyssal onslaught that was to come. In short time, lamhigyns began populating the region, and now tens of thousands of these creatures are said to live near the Worldwound alone. Though lamhigyns are rare outside the Worldwound, their appearance elsewhere on Golarion is a sign that chaos-and the pain of draining, pesky stings-is sure to follow."},{"name":"Large Spriggan","cr":3,"xp":800,"alignment":"CE","size":"Large","type":"humanoid","subtypes":["gnome"],"init":3,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+2 armor, +3 Dex, -1 size","hp":34,"hd":"4d8+16","hdvalue":4,"fort":8,"ref":4,"will":1,"speed":[{"type":"land","speed":30}],"melee":"mwk morningstar +9 (2d6 +5)","ranged":"light crossbow +5 (2d6/19-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"flare"},{"spell":"scare"},{"spell":"shatter"}]}],"strength":21,"dexterity":17,"constitution":18,"intelligence":10,"wisdom":10,"charisma":9,"baseatk":3,"cmb":9,"cmd":22,"feats":[{"feat":"Combat Reflexes"},{"feat":"Weapon Focus (morningstar)"}],"skills":[{"skill":"Climb","value":7},{"skill":"Disable Device","value":10},{"skill":"Perception","value":7},{"skill":"Sleight of Hand","value":10},{"skill":"Stealth","value":6}],"languages":["Aklo","Gnome"],"sq":[{"type":"size alteration"},{"type":"spriggan magic"},{"type":"spriggan skills"}],"environments":["any forests","any hills"],"organizations":["solitary","pair","mob (3-12)"],"treasure":"NPC Gear (leather armor, masterwork morningstar, light crossbow with 10 bolts)","description_visual":"Flecks of saliva drip from the corners of this filthy and ill-smelling humanoid, and his large pointed ears twitch at every sound.","group":"Spriggan","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Size Alteration","kind":"Su","details":"At will as a standard action, a spriggan can change his size between Small and Large. Weapons, armor, and other objects on the spriggan's person grow proportionally when he changes size (objects revert to normal size 1 round after a spriggan releases them). When a spriggan becomes Large, his speed increases to 30 ft., he gains +12 Strength, -2 Dexterity, and +6 Constitution, and he takes a -2 size penalty to his AC. While Large, a spriggan cannot use his sneak attack or his racial spell-like abilities (although if he possesses either from class levels or templates, he retains their use in both sizes)."},{"type":"Spriggan Magic","kind":"Ex","details":"A spriggan gains a +1 racial bonus on concentration checks and to save DCs for all of its racial spell-like abilities."},{"type":"Spriggan Skills","kind":"Ex","details":"Climb, Disable Device, Perception, Sleight of Hand, and Stealth are class skills for spriggans."}],"description":"When the gnomes first traveled to the mortal realm from the distant land of the fey, some found the Material Plane so strange and terrifying that they lost their sense of joy. Seeing only the threats of the new world but none of its wonders, they grimly resolved to survive no matter the cost. Their innate magic responded to this twisted goal by reshaping them in mind and body over the course of many generations, transforming them into the creatures known as spriggans. Love, happiness, and beauty have no meaning for these poor souls, so they lead lives of violence and malice. The best they can manage in place of positive emotions is a muted satisfaction when they make another suffer.\n\nSpriggans resemble ugly gnomes with an alien, feral appearance. Many are gaunt and haggard. When magically enlarged, they look the same except much more hale and muscular.","ecology":"","habitat_society":""},{"name":"Lava Child","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"monstrous humanoid","subtypes":["earth","fire"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+1 Dex, +5 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":5,"ref":5,"will":5,"immunities":["earth magic","fire","and metal"],"weaknesses":["vulnerability to cold and water"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10}],"melee":"2 claws +6 (1d4+2), bite +6 (1d4+2 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"magma throwing"},{"type":"rend","details":"2 claws, 1d4+3"}],"strength":15,"dexterity":12,"constitution":14,"intelligence":10,"wisdom":13,"charisma":13,"baseatk":4,"cmb":6,"cmd":17,"feats":[{"feat":"Great Fortitude"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":5},{"skill":"Intimidate","value":8},{"skill":"Knowledge (dungeoneering)","value":1},{"skill":"Knowledge (nature)","value":2},{"skill":"Knowledge (planes)","value":1},{"skill":"Perception","value":8}],"languages":["Common","Draconic","Ignan","Terran"],"sq":[{"type":"earth glide"}],"environments":["any underground","any mountains (volcanic)"],"organizations":["solitary","cyst (2-40)"],"treasure":"standard (no metal, double gems)","description_visual":"This squat, clawed humanoid is hunched and pink-skinned, with an oversized head. Its face is that of a fanged and insane human baby, and its mouth opens far wider than it should.","source":"Misfit Monsters","special_abilities":[{"type":"Earth Glide","kind":"Ex","details":"A burrowing lava child can pass through stone, dirt, metal, lava, or almost any other sort of earth as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripples or other signs of its presence. A move earth spell cast on an area containing a burrowing lava child flings the creature back 30 ft., stunning it for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Immunity to Earth Magic","kind":"Ex","details":"A lava child is immune to any spell or spell-like ability that allows spell resistance and has the earth descriptor."},{"type":"Magma Throwing","kind":"Su","details":"A lava child can cough up a ball of magma into its hand as a move action. It remains hot as long as the lava child holds it, but cools to the ambient temperature 1 round after it is released. A lava child can throw a magma ball as if it were a flask of alchemist's fire, or add its damage to one successful claw attack. It can use this ability a number of times per day equal to its Hit Dice. On any round in which the lava child remains partially immersed in molten stone and doesn't leave it, it may scoop up a handful as a move action and then throw it as if using this ability, but that action doesn't count toward its daily limit."},{"type":"Metal Immunity","kind":"Su","details":"Lava children ignore the presence of metal and are able to pass through it as easily as air. They are immune to metal weapons, and their attacks ignore any AC bonus (including enhancement bonuses) from metal armor and shields."},{"type":"Vulnerability to Cold and Water","kind":"Ex","details":"Spells and effects with the water or cold subtype inflict +50% damage against lava children (though these vulnerabilities don't stack-effects that are both cold and water still deal only an additional +50% damage). Splashing a lava child with at least 1 gallon of water inflicts 1d6 points of nonlethal damage. Immersion in water causes lava children to take 2d6 points of damage per round and affects them as a slow spell while they remain submerged."}],"description":"Lava children are ill-tempered creatures created by shaitan genies. Shaped like stunted humanoids with the hideous heads of fanged infants, they prefer to reside in volcanoes.\n\nTypical lava children are 5 ft. tall and 450 pounds.","ecology":"","habitat_society":""},{"name":"Lesser Host Devil","cr":3,"xp":800,"alignment":"LE","size":"Small","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +2 natural, +1 size","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":7,"will":0,"dr":"5/good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"speed":[{"type":"land","speed":5},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"mwk spear +7 (1d8+1), 2 claws +6 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"noxious breath"},{"type":"summon devil"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"mage hand"},{"spell":"ventriloquism"}]}],"strength":13,"dexterity":17,"constitution":14,"intelligence":7,"wisdom":9,"charisma":8,"baseatk":4,"cmb":4,"cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Hover"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Escape Artist","value":9},{"skill":"Fly","value":11},{"skill":"Perception","value":6},{"skill":"Stealth","value":13}],"languages":["Infernal","telepathy 100 ft."],"sq":[{"type":"superior grappler"},{"type":"shared senses"},{"type":"swarming"}],"environments":["any (Hell)"],"organizations":["solitary","flock (2d4)"],"treasure":"standard (masterwork Small spear)","description_visual":"This tangle of scaly avian limbs furiously beats its double pair of vulture-like wings, keeping its fiendish, horned skull-head aloft. As fetid breath rises from its repulsive, fly-covered visage, clawed arms work together to slash the air with a vicious-looking spear.","group":"Devil","source":"Book of the Damned V1","special_abilities":[{"type":"Superior Grappler","kind":"Ex","details":"A gaav can wield a weapon and still make grapple checks. If it's not wielding a weapon, a gaav gains a +4 bonus on grapple checks. In addition, it takes up to eight gaavs cooperatively to lift a creature that one or more of them is grappling; each gaav can lift up to 50 pounds and still fly without being impeded."},{"type":"Noxious Breath","kind":"Su","details":"Three times per day, a gaav can exhale a breath that reeks of pure corruption upon a creature within 5 ft. The target must make a DC 14 Fortitude save or be sickened for 1d4 rounds. The save DC is Constitution-based. Creatures that successfully save cannot be affected by the same gaav's noxious breath for 24 hours. A delay poison or neutralize poison spell removes the effect from the sickened creature. Creatures with immunity to poison are unaffected, and creatures resistant to poison receive their normal bonus on their saving throws. Once a gaav uses its breath weapon, it can't breathe again until 1d4 rounds later."},{"type":"Shared Senses","kind":"Su","details":"All gaavs and magaavs within 100 ft. of one another share the same senses. Thus, if one individual perceives something (for example, with a successful Perception check), all others within range are immediately aware of it. Senses are instantly relayed from one gaav or magaav to the next, allowing for the senses of a single devil to potentially spread through and inform an entire massive swarm instantly. It is still possible for a gaav to be surprised or flat-footed even if other gaavs nearby are not."},{"type":"Summon Devil","kind":"Su","details":"Once per day a gaav can attempt to summon an imp with a 35% chance of success. This ability is the equivalent of a 3rd-level spell."},{"type":"Swarming","kind":"Ex","details":"Up to two gaavs can share the same space at the same time. If two gaavs in the same square attack the same foe, they are considered to be flanking that foe as if they were in two opposite squares."}],"description":"Hunters of souls, host devils retrieve Hell's most elusive property. Whether souls that have long evaded capture upon the plains of Avernus, damned beings who have somehow managed to escape Hell, or creatures that have reneged upon infernal contracts, vast flocks of these winged fiends swarm from the Pit to recover their prey. Rarely seen alone, host devils travel in great swarms that often number in the thousands. Amid these great hosts flap the swarm leaders, the magaav, fierce mockeries of the angelic form capable of directing and redirecting massive columns of their brethren like the brain of a single colossal infernal beast. Gaavs stand 4 ft. tall and weigh approximately 110 pounds, their wingspans stretching to just over 6 ft. wide. Magaavs stand 5-1/2 ft. tall and weigh 150 pounds, with wingspans reaching 10 ft. across.","ecology":"","habitat_society":""},{"name":"Lion","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":7,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+3 Dex, +3 natural, -1 size","hp":32,"hd":"5d8+10","hdvalue":5,"fort":6,"ref":7,"will":2,"speed":[{"type":"land","speed":40}],"melee":"bite +7 (1d8+5 plus grab), 2 claws +7 (1d4+5)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +7, 1d4+5"}],"strength":21,"dexterity":17,"constitution":15,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":3,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Perception","value":9},{"skill":"Stealth","value":8,"special":"+12 in undergrowth"}],"environments":["warm plains"],"organizations":["solitary","pair","pride (3-10)"],"treasure":"none","description_visual":"This great cat's muscles flex visibly under its skin as it bares its fangs and shakes its thick mane of hair.","source":"PFRPG Bestiary","description":"Male lions are 5 to 8 ft. long and weigh 330 to 550 pounds. Females are slightly smaller but use the same statistics. Lions are usually the top animal predators in their territories, though they resort to scavenging if convenient or necessary. They may kill other predators (such as leopards and hyenas) that encroach upon their haunts, but rarely eat these kills unless game is scarce. Most lions don't selectively hunt humanoids, but occasionally one learns what easy kills they are and becomes a man-eater. Lions prefer plains but can adapt to living in shallow caves as long as there's a large and stable supply of prey to keep them fed.","ecology":"","habitat_society":""},{"name":"Lumber Consortium Enforcer","cr":3,"xp":800,"race":"Human","classes":[{"class":"brawler","level":4}],"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["human"],"init":1,"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+4 armor, +1 Dex","hp":33,"hd":"4d10+11","hdvalue":4,"fort":7,"ref":6,"will":3,"speed":[{"type":"land","speed":30}],"melee":"mwk longspear +9 (1d8+6/x3) or   handaxe +8 (1d6+4/x3) or   unarmed strike +8 (1d8+4)","ranged":"javelin +5 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"knockout","details":"DC 16 1/day"},{"type":"martial flexibility","details":"5/day"}],"strength":18,"dexterity":13,"constitution":14,"intelligence":8,"wisdom":12,"charisma":10,"baseatk":4,"cmb":8,"cmb_special":"+1 vs. trip","cmd":19,"cmd_special":"+1 vs. trip","feats":[{"feat":"Combat Expertise"},{"feat":"Enforcer"},{"feat":"Improved Unarmed Strike"},{"feat":"Intimidating Prowess"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Climb","value":7},{"skill":"Intimidate","value":11},{"skill":"Perception","value":5},{"skill":"Profession (woodcutter)","value":5},{"skill":"Ride","value":4},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":4},{"skill":"Swim","value":7}],"languages":["Common"],"sq":[{"type":"brawler's cunning"},{"type":"martial training"}],"environments":["any forests","any urban (especially Darkmoon Vale)"],"organizations":["solitary","pair","gang (3-12)"],"treasure":"none","description_visual":"This beefy human brawler has the bearing of a thug.","source":"Andoran Birthplace Of Freedom","description":"The Lumber Consortium maintains its monopoly on hardwood imports, exports, and manufacturing in much of Andoran by means of political manipulation and influence (both legal and otherwise), but employs gangs of enforcers to maintain its power and authority on a local level. Some Lumber Consortium enforcers are disaffected mercenaries or soldiers from elsewhere who have been recruited by the consortium to keep order in their company mill towns. Others have risen through the ranks of the company, beginning as simple roughnecks on the logging crews but showing an aptitude for pushing others around and informing on those they see as slackers to the company overseers.\n\nLumber Consortium enforcers serve a dual role as overseers for the company that manage works crews while nominally offering skilled protection from any threats the forest might offer. In reality, enforcers' responsibilities\n\nwithin the company vary wildly based on the talent of the individuals and the whims of their overseers. Though not necessarily well schooled, some enforcers are selected for their cunning, intuition, and ability to motivate underlings by finding methods that keep people in line.\n\nSince the Lumber Consortium considers itself the de facto authority in the lands it claims, these enforcers often take on the role of a police force. While a few do their best to maintain order and pursue justice, others spend more time spying on the populace and arresting people for \"interfering with company business.\" Those living in areas controlled by the consortium are often subjected to threats, intimidation, and even beatings. Occasionally, the enforcers' strong-arm tactics do elicit useful information about people working outside the company's control, but for many enforcers the bullying is its own reward, and a means to maintain a climate of fear and control.","ecology":"","habitat_society":"","gear":"mwk chain shirt, mwk longspear, handaxe, javelins [3], cloak of resistance +1"},{"name":"Magmin","cr":3,"xp":800,"alignment":"CN","size":"Small","type":"outsider","subtypes":["elemental","extraplanar","fire"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["searing aura (20 ft., DC 14)"],"ac":17,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+6 natural, +1 size","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":4,"will":3,"dr":"5/magic","immunities":["elemental traits","fire"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":30}],"melee":"touch +7 (1 fire plus burn) or   slam +7 (1d6+3 plus 1 fire and burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"1d6, DC 14"}],"strength":15,"dexterity":11,"constitution":15,"intelligence":8,"wisdom":10,"charisma":10,"baseatk":4,"cmb":5,"cmd":15,"feats":[{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Climb","value":9},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":11}],"languages":["Ignan"],"sq":[{"type":"heated flesh"}],"environments":["any land (Plane of Fire)"],"organizations":["solitary","gang (2-8)"],"treasure":"standard","description_visual":"Built of fire and magma, this short humanoid radiates intense heat that causes the air around it to shimmer.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Heated Flesh","kind":"Ex","details":"Any metal weapon striking a magmin must succeed at a DC 14 Fortitude save or melt and gain the broken condition. Another strike by the same weapon causes the metal weapon to be destroyed if it fails a second save. Wood weapons are destroyed after only one failed save. Unarmed and natural attacks made against the magmin deal 1 point of fire damage to the attacker. The save DC is Constitution-based."},{"type":"Searing Aura","kind":"Ex","details":"A magmin radiates extremely high temperatures, and any creature that starts its turn within 20 ft. of a magmin must succeed at a DC 14 Fortitude save or take 1d6 points of fire damage. The save DC is Constitution-based."}],"description":"While magmins populate the Plane of Fire, they sometimes slip through elemental rifts into the Material Plane. These rifts usually occur in places of searing heat, such as volcanoes or underground rivers of magma, or in places of strong, unpredictable magic. The latter scenario usually results in more problematic entrances, as magmins tend to accidently set fire to any nearby flammable objects.\n\nThough not courageous, these small outsiders still make formidable foes against any creature without resistance to their intense heat. Their touch incinerates clothing, and creatures that strike their bodies with steel run the risk of reducing their weapons to slag. Magmins' best defense in their homes on the Plane of Fire is in their sheer numbers. Their settlements, dotted with magma pools and leaping geysers of molten rock, teem with staggering numbers of the creatures.\n\nMagmins are paranoid and untrusting. Always fearful of the larger denizens of the Plane of Fire, magmins harangue any interlopers with dozens of questions, asking where they are going, where they came from, and what they are doing near the magmins' precious magma pools. If travelers' answers are unsatisfactory, the magmins try to shuffle the creatures off as quickly as possible. Those who refuse to leave risk being thrown into a pool of liquid rock.\n\nMagmins take great pride in the cultivation of their magma pools. Each magma pool has a different purpose, such as bathing, cooking meals, or relaxation. Magmins add minerals and salts to these pools to properly season them for their intended uses. Cooking pools (sometimes called \"murder pools\" by strangers) burn hotter than most others, and relaxation pools are generally darker than bathing pools.\n\nUpon reaching adulthood, magmins stand 4 ft. tall, their dense compositions giving them a weight of 300 pounds.","ecology":"","habitat_society":""},{"name":"Man-Eating Aurochs","cr":3,"xp":800,"alignment":"CE","size":"Large","type":"magical beast","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"+6 natural, -1 size","hp":31,"hd":"3d10+15","hdvalue":3,"fort":8,"ref":3,"will":10,"defensive_abilities":["natural cunning"],"dr":"5/slashing","speed":[{"type":"land","speed":40}],"melee":"bite +8 (1d8+6), gore +8 (1d8+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"stampede"},{"type":"trample","details":"2d6+9, DC 17"}],"strength":23,"dexterity":10,"constitution":21,"intelligence":4,"wisdom":15,"charisma":8,"baseatk":3,"cmb":11,"cmb_special":"+4 vs. grapple","cmd":25,"feats":[{"feat":"Endurance"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":11},{"skill":"Survival","value":0,"special":"+4 when following tracks"}],"languages":["Abyssal","Common (can't speak)"],"environments":["temperate plains"],"organizations":["solitary","pair","herd (3-30)"],"treasure":"none","description_visual":"No ordinary bovine, this hulking beast has bloodstained horns and sharpened teeth. Its eyes show a malign intelligence.","group":"Man-Eating Animal","source":"AP 74","special_abilities":[{"type":"Stampede","kind":"Ex","details":"A stampede occurs when three or more creatures with stampede make a trample attack while remaining adjacent to each other. While stampeding, the creatures can trample foes of their size of smaller, and the trample's save DC increases by 2."}],"description":"Scholars will explain that though many animals fight to defend their territory and their young, only a few apex predators hunt humanoids for food. Yet any villager across the Inner Sea region can recount tales about man-eating beasts that once lurked in the local wilderness (and might still). Any sort of animal can become a man-eater, from known predators to seemingly harmless herbivores. Though the creatures and locations may change, certain elements remain the same in tales of man-eating animals. Having tasted human flesh, these animals can't be sated by any other type of food. Man-eaters have terrible bites, and hunters' arrows bounce off their hides. Man-eaters are unusually bold, no longer frightened by human presence like their kin. Yet they are also canny, employing tactics no mere animal could conceive. Man-eaters appear able to understand human speech, and some of the more fanciful stories even claim the animals can speak.\n\nA man-eating animal can be distinguished from its common relatives by its carnivorous teeth, enlarged jaws, and the glint of intelligence in its eyes.\n\nEcology\n\nMost tales of man-eating animals are sparked by rabid or starving (but otherwise normal) animals, but true man-eaters do exist. Such abominations are the result of a fiendish spirit fusing with that of a mundane animal. Though not wholly fiendish in nature, the beast gains limited sentience, increased resilience, and unnatural appetites. Despite popular belief, eating humanoid flesh isn't enough to turn an animal into a man-eater. The creature must be exposed to chaotic and evil inf luences, whether from a planar gate, demonic altar, or transformative elixir (such as the blood of Baphomet). Man-eating animals can also result from botched summonings and incomplete exorcisms. A fiendish spark set loose might inhabit an animal's form so that the foul spirit can continue to spread suffering.\n\nMan-eating animals are no longer part of the natural Ecology. They hunt almost ceaselessly, preferring intelligent prey above all else. They rarely die of natural causes, almost always meeting their ends in bloody conf lict. These creatures can and do mate with members of their original species. In cases of multiple births, only one of the litter inherits this corruption, and it soon devours its siblings.\n\nHabitat & Society\n\nIndividual man-eaters might be found anywhere-the freak results of black magic and vicious natures-but they're encountered in numbers only where fiendish inf luence is strong. Man-eating animals are most common in the blasted landscape of the Worldwound, where they nearly outnumber their natural counterparts. In Kyonin, man-eaters have been born to otherwise normal animals, a sign to the elves that Tanglebriar's corruption is expanding.\n\nMan-eating animals, especially large bovines such as aurochs and bison, are sacred to the followers of Baphomet, demon lord of beasts. Away from civilized lands, cults of Baphomet raise small herds of these carnivorous cattle, feeding them on corpses when live victims are unavailable. Man-eating animals serve as guards and pets for dark cultists and the demons they worship. Though too intelligent and willful to be trained like normal animals, man-eaters gladly serve those who encourage their bloodlust. A dissatisfied man-eater, however, is likely to turn on its so-called master the second its master displays a moment of weakness.\n\nWith their rudimentary intelligence, man-eating animals are able to understand the guttural tongue of the Abyss, and to learn common words in the language of those they hunt. Many take advantage of hunters who assume they are dumb animals.\n\nMan-eaters' combination of animal instinct and demonic cunning allows them to more easily hunt their preferred prey: humanoids. Man-eating animals are known to track victims over long distances, their enhanced senses and great endurance allowing them to continue the chase long after their prey becomes fatigued. An innate sense of direction sometimes allows a man-eater to anticipate (or overhear) its victim's destination and reach it before the creature. Even latched gates and animal traps prove ineffective against the man-eater's cunning.","ecology":"Most tales of man-eating animals are sparked by rabid or starving (but otherwise normal) animals, but true man-eaters do exist. Such abominations are the result of a fiendish spirit fusing with that of a mundane animal. Though not wholly fiendish in nature, the beast gains limited sentience, increased resilience, and unnatural appetites. Despite popular belief, eating humanoid flesh isn't enough to turn an animal into a man-eater. The creature must be exposed to chaotic and evil inf luences, whether from a planar gate, demonic altar, or transformative elixir (such as the blood of Baphomet). Man-eating animals can also result from botched summonings and incomplete exorcisms. A fiendish spark set loose might inhabit an animal's form so that the foul spirit can continue to spread suffering.\n\nMan-eating animals are no longer part of the natural Ecology. They hunt almost ceaselessly, preferring intelligent prey above all else. They rarely die of natural causes, almost always meeting their ends in bloody conf lict. These creatures can and do mate with members of their original species. In cases of multiple births, only one of the litter inherits this corruption, and it soon devours its siblings.","habitat_society":"Individual man-eaters might be found anywhere-the freak results of black magic and vicious natures-but they're encountered in numbers only where fiendish inf luence is strong. Man-eating animals are most common in the blasted landscape of the Worldwound, where they nearly outnumber their natural counterparts. In Kyonin, man-eaters have been born to otherwise normal animals, a sign to the elves that Tanglebriar's corruption is expanding.\n\nMan-eating animals, especially large bovines such as aurochs and bison, are sacred to the followers of Baphomet, demon lord of beasts. Away from civilized lands, cults of Baphomet raise small herds of these carnivorous cattle, feeding them on corpses when live victims are unavailable. Man-eating animals serve as guards and pets for dark cultists and the demons they worship. Though too intelligent and willful to be trained like normal animals, man-eaters gladly serve those who encourage their bloodlust. A dissatisfied man-eater, however, is likely to turn on its so-called master the second its master displays a moment of weakness.\n\nWith their rudimentary intelligence, man-eating animals are able to understand the guttural tongue of the Abyss, and to learn common words in the language of those they hunt. Many take advantage of hunters who assume they are dumb animals.\n\nMan-eaters' combination of animal instinct and demonic cunning allows them to more easily hunt their preferred prey: humanoids. Man-eating animals are known to track victims over long distances, their enhanced senses and great endurance allowing them to continue the chase long after their prey becomes fatigued. An innate sense of direction sometimes allows a man-eater to anticipate (or overhear) its victim's destination and reach it before the creature. Even latched gates and animal traps prove ineffective against the man-eater's cunning."},{"name":"Marine Crocodile","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":5,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+1 Dex, +4 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":5,"will":2,"speed":[{"type":"land","speed":15},{"type":"swim","speed":50}],"melee":"bite +7 (1d8+7 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"death dive"}],"strength":20,"dexterity":13,"constitution":17,"intelligence":1,"wisdom":12,"charisma":2,"baseatk":3,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":20,"feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":11},{"skill":"Swim","value":13}],"sq":[{"type":"hold breath"}],"environments":["tropical oceans"],"organizations":["solitary","pair","float (3-6)"],"treasure":"none","description_visual":"This fishlike reptile has a thin, streamlined snout filled with needlelike teeth and a long, flat tail that it uses to propel itself through the water.","group":"Crocodilian","source":"AP 58","special_abilities":[{"type":"Death Dive","kind":"Ex","details":"When grappling a foe of its size or smaller, a marine crocodile can perform a deadly dive upon making a successful grapple check. As it clings to its foe, it uses the force of its powerful tail to propel it downward in the water, allowing it to use both the move and damage actions as part of its grapple attempt. If successful, the marine crocodile maintains its grapple."},{"type":"Hold Breath","kind":"Ex","details":"A marine crocodile can hold its breath a number of rounds equal to 8 times its Constitution score before it risks drowning."}],"description":"The marine crocodile resembles its land-based cousins in general body shape and size, though its legs are a hybrid of webbed ft. and nascent fins. Its long tail is thinner and flatter than those of traditional crocodilians, allowing the marine crocodile to swim with alarming speed as it whips its tail back and forth.\n\nMarine crocodiles generally remain in warm, shallow oceans and seas. They spend most of their time at sea hunting fish, sea mammals, aquatic humanoids, and monstrous humanoids like merfolk, sahuagin, and locathahs. Only when breeding and laying eggs do marine crocodiles venture onto land (where they are slow and clumsy), before returning to the sea.","ecology":"","habitat_society":""},{"name":"Medium Air Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+5 Dex, +1 dodge, +3 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":9,"will":1,"defensive_abilities":["air mastery"],"immunities":["elemental traits"],"speed":[{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"slam +9 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"whirlwind","details":"DC 14"}],"strength":14,"dexterity":21,"constitution":14,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":6,"cmd":22,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Escape Artist","value":9},{"skill":"Fly","value":17},{"skill":"Knowledge (planes)","value":1},{"skill":"Perception","value":7},{"skill":"Stealth","value":10}],"languages":["Auran"],"environments":["any (Plane of Air)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This cloud-like creature has dark hollows reminiscent of eyes and a mouth, and a howling wind whips it into ominous shapes.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack and damage rolls against an air elemental."}],"description":"Air elementals are fast, flying creatures made of living air. Primitive and territorial, they resent being summoned or doing the bidding of mortals, and much prefer to spend their time on the Plane of Air, swooping and racing through the endless skies. Although all air elementals of a similar size have identical statistics, the exact appearance of an air elemental can vary wildly between individuals. One might be an animated vortex of wind and smoke, while another might be a smoky bird-like creature with glowing eyes and wind for wings. An air elemental prefers to attack flying or otherwise airbone targets, not only because its mastery over flight gives it a slight advantage, but also because it detests the thought of having to touch the ground. An air elemental can move underwater, and although it is an elemental and thus runs no risk of drowning, it has no ranks in Swim and loses much of its speed and mobility when underwater. Whirlwind Whirlwind Elemental Height Weight Save DC Height Small 4 ft. 1 lb. 12 10-20 ft. Medium 8 ft. 2 lbs. 14 10-30 ft. Large 16 ft. 4 lbs. 18 10-40 ft. Huge 32 ft. 8 lbs. 22 10-50 ft. Greater 36 ft. 10 lbs. 23 10-60 ft. Elder 40 ft. 12 lbs. 27 10-60 ft.","ecology":"","habitat_society":""},{"name":"Medium Earth Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":18,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"-1 Dex, +9 natural","hp":34,"hd":"4d10+12","hdvalue":4,"fort":7,"ref":0,"will":4,"immunities":["elemental traits"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20}],"speed_mod":"earth glide","melee":"slam +9 (1d8+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"earth mastery"}],"strength":20,"dexterity":8,"constitution":17,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":9,"cmd":18,"feats":[{"feat":"Cleave"},{"feat":"Improved Bull Rush","type":"bonus"},{"feat":"Power Attack"}],"skills":[{"skill":"Appraise","value":1},{"skill":"Climb","value":10},{"skill":"Knowledge (dungeoneering)","value":2},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":7},{"skill":"Stealth","value":3}],"languages":["Terran"],"environments":["any (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This hulking, roughly humanoid creature of dirt and stone explodes up from the earth, faceless save for two glowing gemstone eyes.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Earth Glide","kind":"Ex","details":"A burrowing earth elemental can pass through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water. If protected against fire damage, it can even glide through lava. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A move earth spell cast on an area containing a burrowing earth elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Earth Mastery","kind":"Ex","details":"An earth elemental gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the elemental takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the elemental is initiating or resisting these kinds of attacks. (These modifiers are not included in the statistics block.)"}],"description":"Earth elementals are plodding, stubborn creatures made of living stone or earth. When utterly still, they resemble a heap of stone or a small hill. When an earth elemental lumbers into action, its actual appearance can vary, although its statistics remain identical to other elementals of its size. Most earth elementals look like terrestrial animals made out of rock, earth, or even crystal, with glowing gemstones for eyes. Larger earth elementals often have a stony humanoid appearance. Bits of vegetation frequently grow in the soil that makes up parts of an earth elemental's body. Elemental Height Weight Small 4 ft. 80 lbs. Medium 8 ft. 750 lbs. Large 16 ft. 6,000 lbs. Huge 32 ft. 48,000 lbs. Greater 36 ft. 54,000 lbs. Elder 40 ft. 60,000 lbs.","ecology":"","habitat_society":""},{"name":"Medium Fire Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["elemental","extraplanar","fire"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +3 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":7,"will":1,"immunities":["elemental traits","fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":50}],"melee":"slam +7 (1d6+1 plus burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"1d6, DC 14"}],"strength":12,"dexterity":17,"constitution":14,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":5,"cmd":19,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Mobility"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Climb","value":5},{"skill":"Escape Artist","value":8},{"skill":"Intimidate","value":5},{"skill":"Knowledge (planes)","value":1},{"skill":"Perception","value":7}],"languages":["Ignan"],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This creature looks like a living, mobile bonfire, tongues of flame reaching out in search of things to burn.","group":"Elemental","source":"PFRPG Bestiary","description":"Fire elementals are quick, cruel creatures of living flame. They enjoy frightening beings weaker than themselves, and terrorizing any creature they can set on fire. A fire elemental cannot enter water or any other nonf lammable liquid. A body of water is an impassible barrier unless the fire elemental can step or jump over it or the water is covered with a flammable material (such as a layer of oil). Fire elementals vary in appearance-they usually manifest as coiling serpentine forms made of smoke and lame, but some fire elementals take on shapes more akin to humans, demons, or other monsters in order to increase the terror of their sudden appearance. Features on a fire elemental's body are made by darker bits of flame or patches of semi-stable smoke, ash, and cinders. Elemental Height Weight Small 4 ft. 1 lb. Medium 8 ft. 2 lbs. Large 16 ft. 4 lbs. Huge 32 ft. 8 lbs. Greater 36 ft. 10 lbs. Elder 40 ft. 12 lbs.","ecology":"","habitat_society":""},{"name":"Medium Ice Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["air","cold","elemental","extraplanar","water"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"snow vision"}],"ac":16,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+6 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":4,"will":1,"immunities":["cold","elemental traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20,"special":"ice and snow only"},{"type":"swim","speed":60}],"melee":"slam +7 (1d6+4 plus 1d4 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"numbing cold","details":"DC 14"}],"strength":16,"dexterity":10,"constitution":15,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":7,"cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Cleave"},{"feat":"Power Attack"}],"skills":[{"skill":"Knowledge (planes)","value":4},{"skill":"Perception","value":7},{"skill":"Stealth","value":7},{"skill":"Swim","value":11}],"languages":["Aquan"],"sq":[{"type":"ice glide"},{"type":"icewalking"}],"environments":["any land (Plane of Water)","any water (Plane of Water)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"From the waist up, this icy creature's features are humanoid, but below its body is a snake-like, slithering tail.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Ice Glide","kind":"Su","details":"A burrowing ice elemental can pass through nonmagical ice and snow as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A control water spell cast on an area containing a burrowing ice elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Icewalking","kind":"Ex","details":"This ability works like the spider climb spell, but the surfaces the elemental climbs must be icy. The elemental can move across icy surfaces without penalty and doesn't need to make Acrobatics checks to run or charge on ice."},{"type":"Numbing Cold","kind":"Su","details":"When an ice elemental deals cold damage to a creature, that creature must succeed on a Fortitude save or be staggered for 1 round. The save DC is listed in the elemental's stat block and is Constitution-based."},{"type":"Snow Vision","kind":"Ex","details":"An ice elemental can see perfectly well in snowy conditions and doesn't take any penalties on Perception checks while in snow."}],"description":"Ice elementals are creatures made of animated snow and ice. They form in especially cold parts of the Plane of Water and along its border with the Plane of Air, where giant icebergs careen off of world-high waterfalls into the open sky. Ice elementals vary in their exact appearance.","ecology":"","habitat_society":""},{"name":"Medium Lightning Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":15,"ac_flat_footed":11,"ac_mods":"+4 Dex, +1 dodge, +1 natural","hp":26,"hd":"4d10+4","hdvalue":4,"fort":5,"ref":8,"will":1,"immunities":["electricity","elemental traits"],"speed":[{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"slam +8 (1d6+3 plus 1d4 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"metal mastery"},{"type":"spark leap"}],"strength":14,"dexterity":19,"constitution":12,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":6,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Escape Artist","value":9},{"skill":"Fly","value":12},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":7}],"languages":["Auran"],"environments":["any (Plane of Air)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This creature looks like a dark storm cloud, with sparks suggesting eyes and long sweeping arms charged with bolts of lightning.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Metal Mastery","kind":"Ex","details":"A lightning elemental gains a +3 bonus on attack rolls if its opponent is wearing metal armor, is wielding a metal weapon, or is made of metal (such as an iron golem)."},{"type":"Spark Leap","kind":"Ex","details":"A lightning elemental gains a +10 bonus on bull rush, disarm, overrun, and trip attacks when it charges a creature against whom its metal mastery ability applies."}],"description":"Though most think of the Plane of Air as a vast expanse of clear sky, that plane also holds the power of the storm, including monstrous hurricanes larger than entire worlds and thunderstorms whose peals and claps can shatter stone. Whether lightning elementals are the byproduct of common air elementals spending too much time near these electrically charged storms or are merely calved off like forgotten flurries, they are aggressive and almost suicidal in their willingness to leap into battle. They particularly enjoy attacking creatures that are made of metal and creatures that wear metal armor or wield metal weapons. Many lightning elementals have a roughly humanoid shape, but some prefer animalistic shapes (particularly birds and dragons), and a few appear to be nothing more than large disembodied heads made of dark clouds with flickering lightning tongues. Regardless of the shape a lightning elemental takes, the air around the creature hums and throbs with the promise of electrocution and the tangy stink of ozone.","ecology":"","habitat_society":""},{"name":"Medium Magma Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["earth","elemental","extraplanar","fire"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"-1 Dex, +7 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":3,"will":1,"immunities":["fire","elemental traits"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20}],"speed_mod":"earth glide","melee":"slam +6 (1d6+3 plus burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"1d4, DC 12"},{"type":"lava puddle"}],"strength":14,"dexterity":8,"constitution":15,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":6,"cmd":15,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Knowledge (dungeoneering)","value":4},{"skill":"Perception","value":7},{"skill":"Stealth","value":6}],"languages":["Ignan"],"sq":[{"type":"earth glide"}],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This rocky monster glows with an internal heat. Red light spills from its eyes and mouth, as well as fractures in its outer surface.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Burn","kind":"Ex","details":"A magma elemental's burn DC includes a -2 racial penalty, as their fires don't burn quite as hot as true elemental flames."},{"type":"Earth Glide","kind":"Ex","details":"A burrowing magma elemental can pass through stone, dirt, lava, or almost any other sort of earth except metal as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple, though the area it passes through feels warm for 1 round afterward and often retains a strangely smooth texture, as if the stone had been polished. A move earth spell cast on an area containing a burrowing magma elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Lava Puddle","kind":"Su","details":"Once per day as a full-round action, a magma elemental can vomit forth a puddle of lava that fills its space to a depth of 2-3 inches and counts as difficult terrain. Any creature that moves through this puddle of lava takes 2d6 points of fire damage. This damage continues for 1d3 rounds after the creature leaves the lava pool, although then it only inflicts 1d6 points of fire damage per round. The lava puddle solidifies and is safe to touch after a number of rounds equal to the elemental's Hit Dice. At the GM's discretion, this puddle of lava could start secondary fires."}],"description":"In the border areas between the Plane of Earth and Plane of Fire, volcanoes and continent-sized lava flows are commonplace. Elementals in this area tend to have aspects of both planes, and the typical sort is the magma elemental, an earth elemental with a core of liquid fire. Magma elementals generally have a somewhat feral or bestial appearance.","ecology":"","habitat_society":""},{"name":"Medium Mud Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["earth","elemental","extraplanar","water"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"ac":16,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+6 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":4,"will":1,"immunities":["acid","elemental traits"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":10},{"type":"swim","speed":30}],"speed_mod":"earth glide","melee":"slam +7 (1d6+4 plus entrap)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"entrap","details":"DC 14, 10 minutes, hardness 5, hp 5"}],"strength":16,"dexterity":10,"constitution":15,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":7,"cmd":17,"feats":[{"feat":"Cleave"},{"feat":"Improved Bull Rush","type":"bonus"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":8},{"skill":"Escape Artist","value":5},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":7},{"skill":"Stealth","value":5},{"skill":"Swim","value":11}],"languages":["Terran"],"environments":["any land (Plane of Earth)","any water (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This animate pile of mud seems barely able to maintain the semblance of a humanoid form made of dripping sludge.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Earth Glide","kind":"Ex","details":"A burrowing mud elemental can pass through dirt, gravel, or other loose or porous solid matter as easily as a fish swims through water. It cannot use this ability to pass through a solid barrier such as a stone or brick wall. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A move earth spell cast on an area containing a burrowing mud elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Entrap","kind":"Ex","details":"The mud from an elemental's entrap ability can be washed away in 1d3 rounds of immersion in water."}],"description":"Where the Plane of Earth borders the Plane of Water, a mixing of the fundamental elements occurs-it is in this borderland that the mud elementals dwell. Scorned by earth and water elementals, mud elementals usually look like vaguely recognizable blobs of mud in the shape of a Material Plane creature, whether a humanoid, an animal, or even an immense insect. The exact density of their muddy bodies varies-some might be composed of silty water, while others are thick, like river clay. Large and powerful mud elementals tend to have worm-like, reptilian, or frog-like forms.","ecology":"","habitat_society":""},{"name":"Medium Water Elemental","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["elemental","extraplanar","water"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+1 Dex, +6 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":5,"will":1,"immunities":["elemental traits"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":90}],"melee":"slam +7 (1d8+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drench"},{"type":"vortex","details":"DC 15"},{"type":"water mastery"}],"strength":16,"dexterity":12,"constitution":15,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":4,"cmb":7,"cmd":18,"feats":[{"feat":"Cleave"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Escape Artist","value":6},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":5},{"skill":"Stealth","value":6},{"skill":"Swim","value":16}],"languages":["Aquan"],"environments":["any (Plane of Water)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This translucent creature's shape shifts between a spinning column of water and a crashing wave.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Drench","kind":"Ex","details":"The elemental's touch puts out nonmagical flames of Large size or smaller. The creature can dispel magical fire it touches as dispel magic (caster level equals elemental's HD)."},{"type":"Vortex","kind":"Su","details":"A water elemental can create a whirlpool as a standard action, at will. This ability functions identically to the whirlwind special attack, but can only form underwater and cannot leave the water."},{"type":"Water Mastery","kind":"Ex","details":"A water elemental gains a +1 bonus on attack and damage rolls if both it and its opponent are touching water. If the opponent or the elemental is touching the ground, the elemental takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the elemental is initiating or resisting these kinds of attacks."}],"description":"Water elementals are patient, relentless creatures made of living fresh or salt water. They prefer to hide or drag their opponents into the water to gain an advantage. As with other elementals, all water elementals have their own unique shapes and appearances. Most appear as wave-like creatures with vaguely humanoid faces and smaller wave \"arms\" to either side. Another common form is that of any aquatic creature, such as a shark or octopus, but made entirely out of water. Elemental Height Weight Vortex Save DC Vortex Height Small 4 ft. 34 lbs. 13 10-20 ft. Medium 8 ft. 280 lbs. 15 10-30 ft. Large 16 ft. 2,250 lbs. 19 10-40 ft. Huge 32 ft. 18,000 lbs. 22 10-50 ft. Greater 36 ft. 21,000 lbs. 25 10-60 ft. Elder 40 ft. 24,000 lbs. 28 10-60 ft.","ecology":"","habitat_society":""},{"name":"Medusa Head","cr":3,"xp":800,"alignment":"NE","size":"Small","type":"undead","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+1 Dex, +3 natural, +1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":3,"ref":2,"will":4,"immunities":["undead traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"bite +6 (1d4+2 plus petrifying bite)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":12,"wisdom":11,"charisma":15,"baseatk":3,"cmb":4,"cmd":15,"cmd_special":"can't be tripped","feats":[{"feat":"Flyby Attack","type":"bonus"}],"languages":["Common"],"environments":["any"],"organizations":["solitary","pair","trio"],"treasure":"none","description_visual":"This humanoid head floats silently and ominously, bits of flesh still hanging from its face and graying teeth clattering slightly as it bobs in the air.","group":"Beheaded","source":"AP 43","special_abilities":[{"type":"Petrifying Bite","kind":"Su","details":"Creatures bitten by a medusa head must make a DC 14 Fortitude save or turn to stone for 1d4 rounds. Targets immune to poison are immune to this effect. The save DC is Charisma-based."}],"description":"Beheaded are floating skulls or severed heads whose bodies have long since abandoned them, either in the moment of death or long after. Reanimated via dark magic, these horrors are usually created as mindless sentinels for dungeons or lairs. Beheaded silently hover at about eye-level, often making them the last thing a casual wanderer or careless villager in an infested area ever sees. Creating Beheaded Spellcasters might create and employ beheaded in multiple ways. Animating Beheaded: A magic-user can create any form of beheaded from a severed head of the appropriate size or creature. The spellcaster must cast the spell animate dead using an onyx gem worth at least 100 gp, followed by the spell fly on the head to be animated. The creator can only create a number of Hit Dice of beheaded equal to the amount allowed by animate dead. Beheaded with the variant abilities below can also be created, though for the purposes of how many can be created, they are treated as if they had one additional Hit Die for each additional ability. Beheaded count against the number of Hit Dice of skeletons or zombies that can be created using animate dead and vise versa. Beheaded Familiars: Using the Improved Familiar feat, a spellcaster can gain an obedient severed head as a familiar. The character must be at least caster level 3rd to acquire the severed head. This creature is always neutral evil. Although any type of magic-user with the proper requisites can take a severed head as a familiar, necromancers and undead wizards employ them most frequently. Variant Beheaded The following are variant abilities that a beheaded might possess. These traits can be mixed and matched in any way and applied to any of the beheaded listed above. Each ability increases the CR of the beheaded by the listed amount. Belching (+1 CR): A belching beheaded gains the ability to spew raw energy from its mouth, giving it a ranged touch attack that does 1d6 damage of a specific type (acid, cold, electric, or fire) chosen at the time of the beheaded's animation. Burning (+1 CR): This beheaded is similar to the flaming skull; however, the fire not only surrounds the skull, but can pass on to those it attacks. The fire that consumes the head can be any color the animator chooses, though blue is one of the most common. A burning skull gains the burn (1d6) special ability when using its slam attack, where the Reflex save DC is 10 + 1/2 the burning skull's racial HD + the burning skull's Cha modifier. Grabbing (+0 CR): This type of beheaded has long tendrils of ragged hair. It gains the grab special ability when using its slam attack, and can attempt to grapple any creature of Medium size or smaller in this way Screaming (+0 CR): Once every 1d4 rounds, a screaming beheaded can open its jaw and emit a bone-chilling scream. All creatures within 30 ft. must make a Will save or be shaken for 1d4 rounds. The save DC is equal to 10 + 1/2 the screaming skull's racial HD + the screaming skull's Cha modifier. This is a sonic mind-affecting fear effect. Whether or not the save is successful, an affected creature is immune to the same beheaded's scream for 24 hours.","ecology":"","habitat_society":""},{"name":"Air Mephit","cr":3,"xp":800,"alignment":"N","size":"Small","type":"outsider","subtypes":["air"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 Dex, +1 dodge, +3 natural, +1 size","hp":19,"hd":"3d10+3","hdvalue":3,"hp_mods":["fast healing 2"],"fort":2,"ref":5,"will":3,"dr":"5/magic","speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"2 claws +5 (1d3+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"15-foot cone, 1d8 slashing, Reflex DC 13 for half"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/hour","spells":[{"spell":"blur"}]},{"frequency":"1/day","spells":[{"spell":"gust of wind"},{"spell":"summon","details":"level 2, 1 mephit of the same type 25%"}]}],"strength":13,"dexterity":15,"constitution":12,"intelligence":6,"wisdom":11,"charisma":14,"baseatk":3,"cmb":3,"cmd":15,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Fly","value":10},{"skill":"Perception","value":6},{"skill":"Stealth","value":12}],"languages":["Common","one appropriate elemental language (Aquan, Auran, Ignan, or Terran)"],"environments":["any (Plane of Air)"],"organizations":["solitary","pair","gang (3-6)","mob (7-12)"],"treasure":"standard","description_visual":"This small humanoid creature has thin, leathery wings, small horns, and a mischievous smile.","source":"PFRPG Bestiary","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"An Air Mephit can unleash a cone of sand and grit that deals 1d8 slashing damage every 4 rounds as a standard action. The DC is Constitution-based and includes a +1 racial bonus."},{"type":"Fast Healing","kind":"Ex","details":"Works only in gusty and windy areas."}],"description":"Mephits are the servants of powerful elemental creatures. Key sites and locations on the elemental planes are full of mephits scurrying about on important errands or duties. Each mephit is associated with one element that defines its spells and abilities. These mephits are whimsical and prone to distraction.","ecology":"","habitat_society":""}];
